      {id:"hotshot-harder",name:"Carl’s HotShot Golf Mat System Harder (GEL)",pricing:"fixed",url:URLS.hotshot,pricesUsd:{"4x5":699.95,"5x8":965.90,"4x9":979.95,"6x10":1259.95}}
